pub(crate) fn doctor_record_storage_bytes(
    bytes_by_class: &mut BTreeMap<String, DoctorStorageAssetClassBreakdown>,
    asset_class: DoctorAssetClass,
    relative_path: &Path,
    bytes: u64,
) {
    let class_name = doctor_asset_class_name(asset_class);
    let entry = bytes_by_class
        .entry(class_name)
        .or_insert_with(|| doctor_storage_breakdown_for_class(asset_class));
    entry.bytes = entry.bytes.saturating_add(bytes);
    entry.file_count += 1;
    if entry.example_paths.len() < 3 {
        entry
            .example_paths
            .push(relative_path.display().to_string());
    }
}


pub(crate) fn doctor_collect_storage_bytes_by_class(
    data_dir: &Path,
) -> (
    BTreeMap<String, DoctorStorageAssetClassBreakdown>,
    Vec<String>,
) {
    let mut bytes_by_class = BTreeMap::new();
    let mut warnings = Vec::new();
    if !data_dir.exists() {
        return (bytes_by_class, warnings);
    }

    let scan_root = std::fs::canonicalize(data_dir).unwrap_or_else(|_| data_dir.to_path_buf());
    for entry in walkdir::WalkDir::new(&scan_root)
        .follow_links(false)
        .into_iter()
    {
        let entry = match entry {
            Ok(entry) => entry,
            Err(err) => {
                warnings.push(format!("storage inventory skipped an entry: {err}"));
                continue;
            }
        };
        let Ok(metadata) = std::fs::symlink_metadata(entry.path()) else {
            warnings.push(format!(
                "storage inventory could not stat {}",
                entry.path().display()
            ));
            continue;
        };
        if !(metadata.is_file() || metadata.file_type().is_symlink()) {
            continue;
        }
        let relative_path = entry
            .path()
            .strip_prefix(&scan_root)
            .unwrap_or(entry.path());
        let asset_class = doctor_classify_storage_relative_path(relative_path);
        if asset_class == DoctorAssetClass::Unknown {
            warnings.push(format!(
                "storage inventory classified {} as unknown and protected it from cleanup",
                relative_path.display()
            ));
        }
        doctor_record_storage_bytes(
            &mut bytes_by_class,
            asset_class,
            relative_path,
            metadata.len(),
        );
    }
    (bytes_by_class, warnings)
}


pub(crate) fn doctor_storage_pressure_action(
    low_disk_risk: &str,
    reclaimable_derived_bytes: u64,
    precious_evidence_bytes: u64,
) -> String {
    if low_disk_risk == "low_free_space" && reclaimable_derived_bytes > 0 {
        "Low free space: inspect the cleanup dry-run and apply only fingerprint-approved derived cleanup; preserve raw mirrors, archive DBs, backups, receipts, configs, bookmarks, and source evidence.".to_string()
    } else if low_disk_risk == "low_free_space" && precious_evidence_bytes > 0 {
        "Low free space: use verified export or archive relocation for precious evidence before reclaiming space; do not delete cass archive evidence manually.".to_string()
    } else if low_disk_risk == "low_free_space" {
        "Low free space: free non-cass space or run doctor cleanup dry-run before any mutation."
            .to_string()
    } else if reclaimable_derived_bytes > 0 {
        "No immediate low-disk risk: derived reclaimable bytes exist, but cleanup still requires an explicit dry-run fingerprint.".to_string()
    } else if precious_evidence_bytes > 0 {
        "No immediate low-disk risk: monitor precious archive growth and use verified export or relocation if it outgrows this disk.".to_string()
    } else {
        "No immediate storage-pressure action is needed.".to_string()
    }
}


pub(crate) fn build_doctor_storage_pressure_report(
    data_dir: &Path,
    probe_path: PathBuf,
    available_space: io::Result<u64>,
    used_test_override: bool,
    full_rebuild_readiness: DoctorFullRebuildReadinessReport,
) -> DoctorStoragePressureReport {
    let (bytes_by_class, classification_warnings) = doctor_collect_storage_bytes_by_class(data_dir);
    let mut total_accounted_bytes = 0_u64;
    let mut reclaimable_derived_bytes = 0_u64;
    let mut precious_evidence_bytes = 0_u64;
    let mut protected_non_reclaimable_bytes = 0_u64;
    let mut unknown_bytes = 0_u64;
    let mut reclaimable_bytes_by_class = BTreeMap::new();
    let mut precious_bytes_by_class = BTreeMap::new();
    let mut protected_bytes_by_class = BTreeMap::new();
    let mut safe_cleanup_scope = Vec::new();
    let mut precious_evidence_classes = Vec::new();

    for (class_name, breakdown) in &bytes_by_class {
        total_accounted_bytes = total_accounted_bytes.saturating_add(breakdown.bytes);
        if breakdown.reclaimable {
            reclaimable_derived_bytes = reclaimable_derived_bytes.saturating_add(breakdown.bytes);
            reclaimable_bytes_by_class.insert(class_name.clone(), breakdown.bytes);
            safe_cleanup_scope.push(class_name.clone());
        } else {
            protected_non_reclaimable_bytes =
                protected_non_reclaimable_bytes.saturating_add(breakdown.bytes);
            protected_bytes_by_class.insert(class_name.clone(), breakdown.bytes);
        }
        if breakdown.precious {
            precious_evidence_bytes = precious_evidence_bytes.saturating_add(breakdown.bytes);
            precious_bytes_by_class.insert(class_name.clone(), breakdown.bytes);
            precious_evidence_classes.push(class_name.clone());
        }
        if class_name == "unknown" {
            unknown_bytes = unknown_bytes.saturating_add(breakdown.bytes);
        }
    }

    safe_cleanup_scope.sort();
    precious_evidence_classes.sort();
    let (status, available_bytes, low_disk_risk, mut notes) = match available_space {
        Ok(available_bytes) => {
            let status = if available_bytes < DOCTOR_STORAGE_MIN_FREE_BYTES {
                "warn"
            } else {
                "ok"
            };
            let low_disk_risk = if status == "warn" {
                "low_free_space"
            } else {
                "none"
            };
            let notes = vec![if status == "warn" {
                format!(
                    "Available space is below the doctor safety floor of {} bytes; free space without deleting cass archive evidence.",
                    DOCTOR_STORAGE_MIN_FREE_BYTES
                )
            } else {
                "Available space is above the doctor safety floor.".to_string()
            }];
            (
                status.to_string(),
                Some(available_bytes),
                low_disk_risk.to_string(),
                notes,
            )
        }
        Err(err) => (
            "unknown".to_string(),
            None,
            "unknown".to_string(),
            vec![format!(
                "Storage pressure was not checked because free-space probing failed: {err}"
            )],
        ),
    };

    if used_test_override {
        notes.push("Storage pressure used the deterministic doctor E2E test override.".to_string());
    }
    notes.push(format!(
        "Storage inventory accounted for {total_accounted_bytes} bytes: {reclaimable_derived_bytes} derived-reclaimable bytes and {precious_evidence_bytes} precious evidence bytes."
    ));
    if precious_evidence_bytes > 0 {
        notes.push(
            "Precious evidence bytes are not cleanup candidates; use verified export, backup, or relocation workflows instead."
                .to_string(),
        );
    }
    if reclaimable_derived_bytes > 0 {
        notes.push(
            "Reclaimable derived bytes still require cleanup dry-run approval and a matching fingerprint before apply."
                .to_string(),
        );
    }
    if let Some(note) = full_rebuild_readiness.notes.first() {
        notes.push(note.clone());
    }

    let recommended_action = doctor_storage_pressure_action(
        &low_disk_risk,
        reclaimable_derived_bytes,
        precious_evidence_bytes,
    );

    DoctorStoragePressureReport {
        schema_version: 3,
        status,
        data_dir_exists: data_dir.exists(),
        probe_path: probe_path.display().to_string(),
        available_bytes,
        min_recommended_free_bytes: DOCTOR_STORAGE_MIN_FREE_BYTES,
        low_disk_risk,
        full_rebuild_readiness,
        total_accounted_bytes,
        reclaimable_derived_bytes,
        precious_evidence_bytes,
        protected_non_reclaimable_bytes,
        unknown_bytes,
        reclaimable_bytes_by_class,
        precious_bytes_by_class,
        protected_bytes_by_class,
        bytes_by_class,
        safe_cleanup_scope,
        precious_evidence_classes,
        classification_warnings,
        recommended_action,
        notes,
    }
}


pub(crate) fn collect_doctor_storage_pressure(data_dir: &Path, db_path: &Path) -> DoctorStoragePressureReport {
    let probe_path = doctor_storage_probe_path(data_dir);
    let used_test_override = dotenvy::var(CASS_TEST_DOCTOR_STORAGE_AVAILABLE_BYTES).is_ok();
    let available_space = doctor_available_space(&probe_path);
    let full_rebuild_readiness = collect_doctor_full_rebuild_readiness(data_dir, db_path);
    build_doctor_storage_pressure_report(
        data_dir,
        probe_path,
        available_space,
        used_test_override,
        full_rebuild_readiness,
    )
}


/// GH#442: the answer to the predicate `cass index --full` refuses on.
///
/// `index --full` / `--force-rebuild` runs the indexer's authoritative-rebuild
/// headroom preflight and, when it refuses, tells the user to run
/// `cass doctor check --json`. Doctor's general `storage_pressure.status`
/// only compares free space against a 1 GiB floor, so it could say `ok`
/// seconds after the indexer refused with a 200 GB requirement. This block
/// reports the requirement by the indexer's own rule
/// ([`indexer::full_rebuild_headroom_projection`]) against the indexer's own
/// probe paths ([`indexer::existing_headroom_probe_paths`]), so the two
/// surfaces cannot disagree.
#[derive(Debug, Clone, Serialize)]
pub(crate) struct DoctorFullRebuildReadinessReport {
    /// `ready` (every probe path has at least `required_bytes` free),
    /// `blocked` (at least one does not), or `unknown` (a probe failed).
    pub(crate) status: String,
    /// `false` when `CASS_INDEX_SKIP_DISK_HEADROOM_CHECK` is set: the indexer
    /// would skip this preflight, so a `blocked` verdict is advisory only.
    pub(crate) enforced: bool,
    /// The rule, stated for humans and agents reading the numbers.
    pub(crate) formula: String,
    pub(crate) required_bytes: u64,
    pub(crate) floor_bytes: u64,
    pub(crate) db_bundle_bytes: u64,
    /// Live lexical bytes: what the current MANIFEST references plus the
    /// index's own bookkeeping files.
    pub(crate) lexical_index_bytes: u64,
    /// nw61n: the generation size the formula charges 9/4 of:
    /// `lexical_index_bytes`, or `db_bundle_bytes` when no live generation
    /// exists to size the rebuild by.
    pub(crate) lexical_rebuild_basis_bytes: u64,
    /// #453: merge-retired segment files still under the lexical index. The
    /// engine's writer-open sweep reclaims them once they have been
    /// unreferenced by both MANIFEST slots for its grace period; a rebuild
    /// never rewrites them, so they are excluded from `required_bytes`.
    pub(crate) retired_segment_bytes: u64,
    /// Number of files behind `retired_segment_bytes`.
    pub(crate) retired_segment_files: usize,
    /// #453: prior generations parked under `index/.lexical-publish-backups/`
    /// (retention keeps the newest; `cass doctor cleanup` reclaims the rest).
    /// Excluded from `required_bytes` for the same reason.
    pub(crate) retained_publish_backup_bytes: u64,
    /// GH #496: an interrupted or failed rebuild's staged generation under
    /// `index/.<name>.rebuild-staging/`. The next rebuild resumes into it or
    /// clears it first, so it is excluded from `required_bytes`.
    pub(crate) rebuild_staging_bytes: u64,
    /// nw61n: failed-rebuild quarantine bundles under `index/` (GH #523
    /// evidence a rebuild never rewrites), excluded from `required_bytes`;
    /// `lexical_rebuild_quarantine` lists them with their retention verdicts.
    pub(crate) quarantine_bytes: u64,
    /// nw61n: the db growth allowance charged (`db_bundle_bytes / 16`).
    pub(crate) db_growth_allowance_bytes: u64,
    /// nw61n: whether the engine's one-time migration repair is still
    /// pending (its `.fsqlite-migration-state` marker absent or incomplete).
    /// Only then is the whole db bundle charged again, for the repair's
    /// `.pre-migration-bak` copy (`migration_copy_bytes`).
    pub(crate) migration_repair_pending: bool,
    pub(crate) migration_copy_bytes: u64,
    /// Free bytes at the most constrained probe path (`None` when unknown).
    pub(crate) available_bytes: Option<u64>,
    /// `required_bytes - available_bytes` when blocked, else 0.
    pub(crate) shortfall_bytes: u64,
    /// The probe path that decided the verdict (least free space, or the
    /// first one that failed to probe).
    pub(crate) probe_path: String,
    /// Every path the indexer's preflight probes, in its order.
    pub(crate) probe_paths: Vec<String>,
    pub(crate) notes: Vec<String>,
}


pub(crate) fn collect_doctor_full_rebuild_readiness(
    data_dir: &Path,
    db_path: &Path,
) -> DoctorFullRebuildReadinessReport {
    let projection = crate::indexer::full_rebuild_headroom_projection(data_dir, db_path);
    let probes: Vec<(PathBuf, io::Result<u64>)> =
        crate::indexer::existing_headroom_probe_paths(data_dir, db_path)
            .into_iter()
            .map(|path| {
                let available = doctor_available_space(&path);
                (path, available)
            })
            .collect();
    build_doctor_full_rebuild_readiness(
        projection,
        probes,
        !crate::indexer::index_disk_headroom_check_disabled(),
    )
}


pub(crate) fn build_doctor_full_rebuild_readiness(
    projection: crate::indexer::FullRebuildHeadroomProjection,
    probes: Vec<(PathBuf, io::Result<u64>)>,
    enforced: bool,
) -> DoctorFullRebuildReadinessReport {
    let required_bytes = projection.required_bytes;
    let probe_paths: Vec<String> = probes
        .iter()
        .map(|(path, _)| path.display().to_string())
        .collect();

    // Mirror the indexer: the first probe that fails is an error, otherwise
    // the verdict is decided by the path with the least free space.
    let mut failed: Option<(String, String)> = None;
    let mut tightest: Option<(String, u64)> = None;
    for (path, available) in probes {
        match available {
            Ok(bytes) => {
                if tightest.as_ref().is_none_or(|(_, best)| bytes < *best) {
                    tightest = Some((path.display().to_string(), bytes));
                }
            }
            Err(err) => {
                if failed.is_none() {
                    failed = Some((path.display().to_string(), err.to_string()));
                }
                break;
            }
        }
    }

    let (status, available_bytes, shortfall_bytes, probe_path, mut notes) = match (failed, tightest)
    {
        (Some((path, err)), _) => (
            "unknown",
            None,
            0,
            path.clone(),
            vec![format!(
                "Full-rebuild readiness is unknown: free-space probing failed at {path}: {err}"
            )],
        ),
        (None, Some((path, available))) => {
            let shortfall = required_bytes.saturating_sub(available);
            if shortfall == 0 {
                (
                    "ready",
                    Some(available),
                    0,
                    path.clone(),
                    // No live free-space figure here: this note is part of
                    // the doctor robot goldens, and the number lives in
                    // `available_bytes` (which the goldens scrub).
                    vec![format!(
                        "A full rebuild (cass index --full / --force-rebuild) needs {required_bytes} bytes free at {path}, and the free space there covers it, so the indexer's headroom preflight would pass."
                    )],
                )
            } else {
                (
                    "blocked",
                    Some(available),
                    shortfall,
                    path.clone(),
                    vec![format!(
                        "A full rebuild (cass index --full / --force-rebuild) needs {required_bytes} bytes free at {path}; {available} bytes are available ({shortfall} bytes short), so the indexer's headroom preflight would refuse. Incremental indexing is unaffected by this verdict."
                    )],
                )
            }
        }
        (None, None) => (
            "unknown",
            None,
            0,
            String::new(),
            vec!["Full-rebuild readiness is unknown: no probe path was available.".to_string()],
        ),
    };
    notes.push(format!(
        "Requirement is {}: lexical index {} bytes, db bundle {} bytes (growth allowance {} bytes{}), floor {} bytes.",
        crate::indexer::FULL_REBUILD_HEADROOM_FORMULA,
        projection.lexical_index_bytes,
        projection.db_bundle_bytes,
        projection.db_growth_allowance_bytes,
        if projection.migration_repair_pending {
            format!(
                "; the engine's one-time migration repair is pending and keeps a copy of the whole bundle, so migration copy {} bytes",
                projection.migration_copy_bytes
            )
        } else {
            String::new()
        },
        projection.floor_bytes
    ));
    if projection.lexical_index_bytes == 0 && projection.lexical_rebuild_basis_bytes > 0 {
        notes.push(format!(
            "There is no live lexical generation to size the rebuild by, so it is sized as the db bundle ({} bytes).",
            projection.lexical_rebuild_basis_bytes
        ));
    }
    if projection.quarantine_bytes > 0 {
        notes.push(format!(
            "{} bytes of failed-rebuild quarantine bundles sit under index/ and are not charged; lexical_rebuild_quarantine lists them with their retention verdicts, and its next_safe_argv previews reclaiming them.",
            projection.quarantine_bytes
        ));
    }
    if projection.retired_segment_bytes > 0 {
        notes.push(format!(
            "The lexical figure counts only bytes the current MANIFEST references; {} merge-retired segment file(s) totalling {} bytes sit next to it and are not charged. The engine unlinks them at the next `cass index` open once they have been unreferenced for its {}-second grace period (`cass index --gc` runs that sweep on its own).",
            projection.retired_segment_files,
            projection.retired_segment_bytes,
            frankensearch::quill::DEFAULT_GARBAGE_GRACE.as_secs()
        ));
    }
    if projection.retained_backup_bytes > 0 {
        notes.push(format!(
            "{} bytes of prior lexical generations are retained under index/.lexical-publish-backups/ and are not charged either; a staged publish prunes them to the retention cap, and `cass doctor cleanup` reclaims them earlier.",
            projection.retained_backup_bytes
        ));
    }
    if projection.rebuild_staging_bytes > 0 {
        notes.push(format!(
            "{} bytes of an interrupted or failed rebuild's staged generation sit under index/ (the .rebuild-staging directory) and are subtracted from the requirement: the next `cass index --full` resumes into them or clears them before starting over, so that space comes back to the rebuild.",
            projection.rebuild_staging_bytes
        ));
    }
    if !enforced {
        notes.push(
            "CASS_INDEX_SKIP_DISK_HEADROOM_CHECK is set, so the indexer would skip this preflight; the verdict is advisory."
                .to_string(),
        );
    }

    DoctorFullRebuildReadinessReport {
        status: status.to_string(),
        enforced,
        formula: crate::indexer::FULL_REBUILD_HEADROOM_FORMULA.to_string(),
        required_bytes,
        floor_bytes: projection.floor_bytes,
        db_bundle_bytes: projection.db_bundle_bytes,
        lexical_index_bytes: projection.lexical_index_bytes,
        lexical_rebuild_basis_bytes: projection.lexical_rebuild_basis_bytes,
        retired_segment_bytes: projection.retired_segment_bytes,
        retired_segment_files: projection.retired_segment_files,
        retained_publish_backup_bytes: projection.retained_backup_bytes,
        rebuild_staging_bytes: projection.rebuild_staging_bytes,
        quarantine_bytes: projection.quarantine_bytes,
        db_growth_allowance_bytes: projection.db_growth_allowance_bytes,
        migration_repair_pending: projection.migration_repair_pending,
        migration_copy_bytes: projection.migration_copy_bytes,
        available_bytes,
        shortfall_bytes,
        probe_path,
        probe_paths,
        notes,
    }
}
